contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that the checker will call with arbitrary inputs.
    // We test that when transfer returns (doesn't revert), it returns true.
    // Additionally we observe whether it reverted when attempting the call.
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // Precondition: match lengths requirement used by C.transfer (it requires _tos.length > 0)
        require(_tos.length > 0 && _tos.length == v.length, "invalid inputs");

        bool reverted;
        bool returnedValue = false;

        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returnedValue = r;
        } catch {
            reverted = true;
        }

        // General rule: if the call did not revert then it must have returned true.
        // This captures the intended guarantee of C.transfer (it returns true on success).
        assert(reverted || returnedValue == true);
    }

    receive() external payable { }
}

